const config: runtime.GetPrismaClientConfig = {
  "previewFeatures": [],
  "clientVersion": "7.9.1",
  "engineVersion": "e922089b7d7502aff4249d5da3420f6fa55fc6ad",
  "activeProvider": "postgresql",
  "inlineSchema": "// ============================================================\n// EVENT MARKETPLACE — SCHEMA (refreshed, supersedes all prior versions)\n//\n// Foundational assumptions locked in so far:\n// - Vendors belong to exactly ONE market (no cross-market offering yet)\n// - A vendor can offer multiple service categories; each category is\n//   independently verified and independently bookable\n// - Identity (KVK, ID/passport) is verified ONCE per vendor and reused\n//   across categories; insurance and category-specific docs are NOT\n//   assumed to carry over unless explicitly confirmed by admin\n// - No application reaches admin until all required documents for\n//   that category are uploaded (client + server-side gated)\n// - Bookings are single-vendor, single-package (no split/pooled\n//   payments at this stage — see Event for the multi-vendor \"project\")\n// - VAT rates are stored as verifiable, sourced data — never assumed\n// ============================================================\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\n// ------------------------------------------------------------\n// ENUMS\n// ------------------------------------------------------------\n\nenum UserRole {\n  SUPER_ADMIN\n  PARTNER\n  CUSTOMER\n}\n\nenum EventStatus {\n  LEAD // scoping in progress, no commitment yet\n  OPPORTUNITY // fully scoped, cost estimate locked, not yet paid\n  ACTIVE // at least one booking is PAID or further\n  COMPLETE // event date has passed\n  ABANDONED // inactive X days with no payment, never converted\n}\n\nenum EventType {\n  SINGLE_VENDOR\n  MULTI_VENDOR\n}\n\nenum BookingStatus {\n  PLANNED\n  AWAITING_PAYMENT\n  PAID\n  CONFIRMED\n  CLOSED_WON\n  CLOSED_LOST\n  CLOSED_CANCELLED_CLIENT\n  CLOSED_CANCELLED_VENDOR\n  CLOSED_RESCHEDULED\n  CLOSED_REFUNDED\n}\n\nenum GuestRole {\n  ORGANIZER_PAYER\n  ATTENDEE\n}\n\nenum DepositType {\n  FLAT\n  PERCENTAGE\n}\n\nenum VendorStatusAction {\n  APPROVED\n  HIDDEN\n  UNHIDDEN\n  SUSPENDED\n}\n\nenum PenaltyReason {\n  VENDOR_CANCELLATION\n  OTHER\n}\n\nenum PenaltyStatus {\n  PENDING\n  DEDUCTED\n  WAIVED\n}\n\n// Applies to a PartnerCategory's path to becoming bookable\nenum ApplicationStatus {\n  DRAFT // vendor still filling in / uploading docs\n  DOCS_COMPLETE // all required docs uploaded, not yet submitted\n  SUBMITTED // vendor has submitted for review\n  INTERVIEW_SCHEDULED // admin has booked a call/interview\n  IN_REVIEW // admin actively verifying docs/KVK/insurance\n  APPROVED // category is live and bookable\n  REJECTED // application denied\n}\n\nenum DocumentType {\n  ID_PASSPORT // person-level identity, verified once per vendor\n  BUSINESS_REGISTRATION // KVK or market equivalent, company-level\n  FOOD_SAFETY_PLAN // e.g. HACCP (NL) or market equivalent\n  FOOD_AUTHORITY_REGISTRATION // e.g. NVWA (NL) or market equivalent\n  BACKGROUND_CHECK // e.g. VOG (NL) or market equivalent\n  OPERATING_LICENSE // e.g. taxi/passenger transport operator licence, venue alcohol licence\n  LIABILITY_INSURANCE\n  REFERENCE_LETTER\n  PORTFOLIO_MEDIA\n  OTHER\n}\n\nenum DocumentStatus {\n  PENDING_REVIEW\n  APPROVED\n  REJECTED\n  EXPIRED\n}\n\nenum VatRateType {\n  STANDARD\n  REDUCED\n  ZERO\n  EXEMPT\n}\n\nenum VatAppliesTo {\n  B2B\n  B2C\n  BOTH\n}\n\n// ------------------------------------------------------------\n// CORE USERS\n// ------------------------------------------------------------\n\nmodel User {\n  id           String   @id @default(cuid())\n  email        String   @unique\n  passwordHash String\n  role         UserRole @default(CUSTOMER)\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  partnerProfile      PartnerProfile?\n  events              Event[]\n  statusLogsMade      VendorStatusLog[]   @relation(\"AdminActor\")\n  documentsReviewed   VendorDocument[]    @relation(\"DocumentReviewer\")\n  applicationsDecided VendorApplication[] @relation(\"ApplicationDecider\")\n  placementsCurated   FeaturedPlacement[] @relation(\"PlacementCurator\")\n}\n\n// ------------------------------------------------------------\n// MARKET — the foundation for multi-country expansion\n// ------------------------------------------------------------\n\nmodel Market {\n  id                String   @id @default(cuid())\n  countryCode       String   @unique // ISO 3166-1 alpha-2, e.g. \"NL\"\n  name              String\n  currency          String // ISO 4217, e.g. \"EUR\"\n  language          String // e.g. \"nl\", \"en\"\n  legalTermsVersion String // current vendor/customer ToS version for this market\n  isActive          Boolean  @default(false)\n  createdAt         DateTime @default(now())\n  updatedAt         DateTime @updatedAt\n\n  categoryRequirements CategoryRequirement[]\n  categoryVatRates     CategoryVatRate[]\n  partners             PartnerProfile[]\n  events               Event[]\n  placements           FeaturedPlacement[]\n}\n\n// ------------------------------------------------------------\n// VENDOR CATEGORIES + PER-MARKET REQUIREMENTS\n// ------------------------------------------------------------\n\nmodel VendorCategory {\n  id   String @id @default(cuid())\n  name String @unique // e.g. \"CATERER\", \"DJ\", \"KIDS_ENTERTAINER\", \"VENUE\", \"OTHER\"\n  slug String @unique\n\n  categoryRequirements CategoryRequirement[]\n  categoryVatRates     CategoryVatRate[]\n  partnerCategories    PartnerCategory[]\n}\n\n// What documents are required for a given category, in a given market.\n// This is the matrix that drives the vendor signup form dynamically.\nmodel CategoryRequirement {\n  id           String       @id @default(cuid())\n  marketId     String\n  categoryId   String\n  documentType DocumentType\n  isRequired   Boolean      @default(true)\n  notes        String?      @db.Text // e.g. \"Required only if handling meat/fish/dairy\"\n\n  market   Market         @relation(fields: [marketId], references: [id], onDelete: Cascade)\n  category VendorCategory @relation(fields: [categoryId], references: [id], onDelete: Cascade)\n\n  @@unique([marketId, categoryId, documentType])\n}\n\n// VAT rate per market/category — stored as sourced, verifiable data.\n// Never trust a hardcoded percentage silently; always trace it.\nmodel CategoryVatRate {\n  id             String       @id @default(cuid())\n  marketId       String\n  categoryId     String\n  rateType       VatRateType\n  ratePercent    Decimal      @db.Decimal(5, 2)\n  appliesTo      VatAppliesTo @default(BOTH) // B2B vs B2C can differ\n  sourceUrl      String       @db.Text // official government source, not a blog/aggregator\n  lastVerifiedAt DateTime\n  verifiedBy     String? // admin/team member who checked it\n  notes          String?      @db.Text // e.g. ambiguous classification, pending legislation\n\n  market   Market         @relation(fields: [marketId], references: [id], onDelete: Cascade)\n  category VendorCategory @relation(fields: [categoryId], references: [id], onDelete: Cascade)\n\n  @@unique([marketId, categoryId, appliesTo])\n}\n\n// ------------------------------------------------------------\n// VENDOR / PARTNER\n// ------------------------------------------------------------\n\nmodel PartnerProfile {\n  id          String @id @default(cuid())\n  userId      String @unique\n  marketId    String\n  companyName String\n  kvkNumber   String // required — company-level, verified once, reused across categories\n  vatNumber   String // required — company-level, verified once, reused across categories\n\n  stripeAccountId String?\n\n  isVisible Boolean @default(true) // approved-but-hidden distinct from never-approved\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  user       User              @relation(fields: [userId], references: [id], onDelete: Cascade)\n  market     Market            @relation(fields: [marketId], references: [id])\n  identity   PartnerIdentity?\n  categories PartnerCategory[]\n  documents  VendorDocument[]\n  statusLogs VendorStatusLog[]\n  penalties  VendorPenalty[]\n  bookings   Booking[]\n}\n\n// The human behind the business — verified once, reused across\n// every category this vendor applies for. Not re-collected per service.\nmodel PartnerIdentity {\n  id            String    @id @default(cuid())\n  partnerId     String    @unique\n  fullName      String\n  idType        String // \"PASSPORT\" | \"NATIONAL_ID\"\n  idDocumentUrl String\n  verified      Boolean   @default(false)\n  verifiedAt    DateTime?\n  verifiedBy    String?\n\n  partner PartnerProfile @relation(fields: [partnerId], references: [id], onDelete: Cascade)\n}\n\n// A vendor's offering within one service category — independently\n// verified, independently bookable. A vendor with 3 categories has\n// 3 of these, each progressing through review on its own timeline.\nmodel PartnerCategory {\n  id         String @id @default(cuid())\n  partnerId  String\n  categoryId String\n\n  status     ApplicationStatus @default(DRAFT)\n  isBookable Boolean           @default(false) // true only once APPROVED\n\n  // Insurance can be company-wide or category-specific — admin decides\n  // whether an existing policy already covers this service line.\n  insuranceAppliesFromExistingPolicy Boolean   @default(false)\n  insuranceConfirmedBy               String?\n  insuranceConfirmedAt               DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  partner     PartnerProfile     @relation(fields: [partnerId], references: [id], onDelete: Cascade)\n  category    VendorCategory     @relation(fields: [categoryId], references: [id])\n  application VendorApplication?\n  documents   VendorDocument[]\n  packages    Package[]\n\n  @@unique([partnerId, categoryId])\n}\n\n// The review workflow/state machine for a single PartnerCategory.\n// A new category added later to an already-approved vendor gets its\n// own VendorApplication, scoped only to what that category needs.\nmodel VendorApplication {\n  id                String            @id @default(cuid())\n  partnerCategoryId String            @unique\n  status            ApplicationStatus @default(DRAFT)\n\n  submittedAt          DateTime?\n  interviewScheduledAt DateTime?\n  interviewConductedBy String?\n  interviewNotes       String?   @db.Text\n\n  kvkVerified   Boolean   @default(false)\n  kvkVerifiedAt DateTime?\n  kvkVerifiedBy String?\n\n  insuranceVerified   Boolean   @default(false)\n  insuranceVerifiedAt DateTime?\n  insuranceVerifiedBy String?\n\n  documentsVerified Boolean @default(false)\n\n  decisionAt      DateTime?\n  decidedById     String?\n  rejectionReason String?   @db.Text\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  partnerCategory PartnerCategory @relation(fields: [partnerCategoryId], references: [id], onDelete: Cascade)\n  decidedBy       User?           @relation(\"ApplicationDecider\", fields: [decidedById], references: [id])\n}\n\n// Uploaded evidence. partnerCategoryId is nullable: company-level docs\n// (ID, KVK proof) are null here and live on PartnerProfile/PartnerIdentity\n// instead, while category-specific docs (HACCP plan, category insurance)\n// are scoped to one PartnerCategory.\nmodel VendorDocument {\n  id                String         @id @default(cuid())\n  partnerId         String\n  partnerCategoryId String?\n  documentType      DocumentType\n  fileUrl           String\n  status            DocumentStatus @default(PENDING_REVIEW)\n  expiresAt         DateTime? // VOG / insurance / HACCP renewals need tracking\n  rejectionReason   String?        @db.Text\n\n  reviewedById String?\n  reviewedAt   DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  partner         PartnerProfile   @relation(fields: [partnerId], references: [id], onDelete: Cascade)\n  partnerCategory PartnerCategory? @relation(fields: [partnerCategoryId], references: [id], onDelete: Cascade)\n  reviewedBy      User?            @relation(\"DocumentReviewer\", fields: [reviewedById], references: [id])\n}\n\n// Audit trail for admin actions on vendor visibility/approval status\nmodel VendorStatusLog {\n  id        String             @id @default(cuid())\n  partnerId String\n  action    VendorStatusAction\n  reason    String             @db.Text\n  adminId   String\n  createdAt DateTime           @default(now())\n\n  partner PartnerProfile @relation(fields: [partnerId], references: [id], onDelete: Cascade)\n  admin   User           @relation(\"AdminActor\", fields: [adminId], references: [id])\n}\n\n// Ledger of penalty charges against a vendor (e.g. vendor-cancellation fee)\nmodel VendorPenalty {\n  id         String        @id @default(cuid())\n  partnerId  String\n  bookingId  String?       @unique\n  amount     Decimal       @db.Decimal(10, 2)\n  reason     PenaltyReason\n  status     PenaltyStatus @default(PENDING)\n  createdAt  DateTime      @default(now())\n  resolvedAt DateTime?\n\n  partner PartnerProfile @relation(fields: [partnerId], references: [id], onDelete: Cascade)\n  booking Booking?       @relation(fields: [bookingId], references: [id])\n}\n\n// ------------------------------------------------------------\n// PACKAGES, TAGS, CANCELLATION POLICY, CURATION\n// ------------------------------------------------------------\n\nmodel Package {\n  id                String   @id @default(cuid())\n  partnerCategoryId String // bookability inherits from the category's approval, not the vendor overall\n  title             String\n  description       String   @db.Text\n  basePrice         Decimal  @db.Decimal(10, 2)\n  maxGuests         Int\n  mediaUrls         String[]\n  isActive          Boolean  @default(true)\n  createdAt         DateTime @default(now())\n  updatedAt         DateTime @updatedAt\n\n  partnerCategory    PartnerCategory     @relation(fields: [partnerCategoryId], references: [id], onDelete: Cascade)\n  tagMappings        PackageTag[]\n  bookings           Booking[]\n  cancellationPolicy CancellationPolicy?\n  featuredPlacements FeaturedPlacement[]\n}\n\n// Vendor-defined commercial terms — structured, not free text,\n// so refunds can eventually be calculated automatically.\nmodel CancellationPolicy {\n  id        String @id @default(cuid())\n  packageId String @unique\n\n  depositType        DepositType\n  depositValue       Decimal     @db.Decimal(10, 2) // flat amount OR percentage, per depositType\n  depositDescription String      @db.Text // vendor's own language, shown at checkout\n\n  // Kept flexible via JSON for MVP; normalize once real patterns emerge.\n  refundTiers Json\n  // e.g. [{ \"daysBeforeEvent\": 14, \"refundPercent\": 100 },\n  //       { \"daysBeforeEvent\": 7,  \"refundPercent\": 50  },\n  //       { \"daysBeforeEvent\": 0,  \"refundPercent\": 0   }]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  package Package @relation(fields: [packageId], references: [id], onDelete: Cascade)\n}\n\n// Vendor's own self-tagging — used for discovery/search\nmodel Tag {\n  id       String       @id @default(cuid())\n  name     String       @unique // e.g. \"Winter\", \"Bachelorette\", \"Amsterdam\"\n  type     String // \"SEASON\" | \"OCCASION\" | \"REGION\" | \"DEMOGRAPHIC\" | \"PRICE_TIER\"\n  packages PackageTag[]\n}\n\nmodel PackageTag {\n  packageId String\n  tagId     String\n\n  package Package @relation(fields: [packageId], references: [id], onDelete: Cascade)\n  tag     Tag     @relation(fields: [tagId], references: [id], onDelete: Cascade)\n\n  @@id([packageId, tagId])\n}\n\n// Admin-controlled curation layer — separate from vendor self-tagging.\n// Lets admin manually feature/rank specific packages per market/region/\n// occasion for marketing campaigns, independent of vendor tagging quality.\nmodel FeaturedPlacement {\n  id          String    @id @default(cuid())\n  packageId   String\n  marketId    String\n  region      String\n  occasionTag String\n  priority    Int       @default(0)\n  isActive    Boolean   @default(true)\n  activeFrom  DateTime?\n  activeTo    DateTime?\n  curatedById String\n  createdAt   DateTime  @default(now())\n\n  package   Package @relation(fields: [packageId], references: [id], onDelete: Cascade)\n  market    Market  @relation(fields: [marketId], references: [id])\n  curatedBy User    @relation(\"PlacementCurator\", fields: [curatedById], references: [id])\n}\n\n// ------------------------------------------------------------\n// EVENT (the customer's project) + BOOKINGS (per-vendor)\n// ------------------------------------------------------------\n\nmodel Event {\n  id         String   @id @default(cuid())\n  customerId String? // nullable: scoping can start before account creation\n  marketId   String\n  title      String // e.g. \"Sarah's Bachelorette Party\"\n  eventType  String // occasion tag, e.g. \"BACHELORETTE\", \"CORPORATE_CHRISTMAS\"\n  eventDate  DateTime\n  region     String\n  guestCount Int\n\n  budgetTotal      Decimal? @db.Decimal(10, 2)\n  budgetPerPerson  Decimal? @db.Decimal(10, 2)\n  payingGuestCount Int? // how many people are contributing financially\n\n  status EventStatus @default(LEAD)\n  type   EventType   @default(SINGLE_VENDOR) // updated in app logic once 2nd booking is added\n\n  shareToken String  @unique @default(cuid()) // view-only public link\n  isPublic   Boolean @default(true)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  customer User?     @relation(fields: [customerId], references: [id])\n  market   Market    @relation(fields: [marketId], references: [id])\n  bookings Booking[]\n}\n\nmodel Booking {\n  id        String @id @default(cuid())\n  eventId   String\n  packageId String\n  partnerId String\n\n  status BookingStatus @default(PLANNED)\n\n  pricePaid Decimal? @db.Decimal(10, 2) // snapshot at time of payment, null while PLANNED\n  currency  String   @default(\"EUR\")\n\n  stripePaymentIntentId String?\n  stripeTransferId      String? // set once payout to vendor is released\n\n  // Reserve/holdback: funds aren't released to vendor immediately on PAID,\n  // which is what makes automatic penalty enforcement on cancellation possible.\n  payoutReleaseAt DateTime?\n  payoutReleased  Boolean   @default(false)\n\n  vendorConfirmedAt      DateTime?\n  vendorResponseDeadline DateTime? // 24-48h window after PAID\n\n  rescheduledFromId String?  @unique\n  rescheduledFrom   Booking? @relation(\"BookingReschedule\", fields: [rescheduledFromId], references: [id])\n  rescheduledTo     Booking? @relation(\"BookingReschedule\")\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  event   Event          @relation(fields: [eventId], references: [id], onDelete: Cascade)\n  package Package        @relation(fields: [packageId], references: [id])\n  partner PartnerProfile @relation(fields: [partnerId], references: [id])\n\n  guests        BookingGuest[]\n  vendorPenalty VendorPenalty?\n}\n\n// Lead booker + attendees, so vendor and platform have full contact visibility\nmodel BookingGuest {\n  id        String    @id @default(cuid())\n  bookingId String\n  email     String\n  role      GuestRole @default(ATTENDEE)\n  createdAt DateTime  @default(now())\n\n  booking Booking @relation(fields: [bookingId], references: [id], onDelete: Cascade)\n\n  @@unique([bookingId, email])\n}\n",
  "runtimeDataModel": {
    "models": {},
    "enums": {},
    "types": {}
  },
  "parameterizationSchema": {
    "strings": [],
    "graph": ""
  }
}

